const body = $json.body;
return {
  json: {
    message: body.message || '',
    schema: body.schema || '',
    guest_id: body.guest_id || ''
  }
};

const webhook   = $('Webhook').first().json.body;
const extracted = $('Extract Fields').first().json;
const context   = $('Fetch AI Context').first().json;

const message = extracted.message || webhook.message || 'Hello';
const schema  = extracted.schema || 'unknown';
const history = webhook.history || [];
const storeName = extracted.store_name || context.store_name || '';
const storeOpen = context.store_open;

const prompts  = context.prompts        || {};
const products = context.products       || [];
const zones    = context.delivery_zones || [];

// --- Language detection from customer message ---
function detectLanguage(text) {
  if (!text) return null;
  if (/[\u4e00-\u9fff]/.test(text)) return 'Chinese';
  if (/[\u0600-\u06ff]/.test(text)) return 'Arabic';
  if (/[\uac00-\ud7af]/.test(text)) return 'Korean';
  if (/[\u3040-\u30ff]/.test(text)) return 'Japanese';
  if (/[\u0e00-\u0e7f]/.test(text)) return 'Thai';
  if (/[\u0900-\u097f]/.test(text)) return 'Hindi';
  if (/[\u0b80-\u0bff]/.test(text)) return 'Tamil';
  if (/\b(aku|saya|kamu|anda|ini|itu|mau|bisa|tidak|sudah|belum|harga|pesan|beli|ada|gak|nggak|dong|deh|nih|bang|kak|pak|bu|iya|tolong|makasih|berapa|gimana|bagaimana|apakah|kenapa|kapan|dimana|siapa|apa)\b/i.test(text)) return 'Indonesian';
  if (/\b(saya|awak|nak|hendak|boleh|dah|harga|beli|ada|lah|loh|mah|terima kasih|tak|hendak)\b/i.test(text)) return 'Malay';
  if (/\b(ako|ikaw|siya|ang|ng|mga|po|opo|gusto|bili|kumusta|salamat|oo|hindi)\b/i.test(text)) return 'Filipino';
  if (/\b(tôi|bạn|của|không|có|được|muốn|mua|hàng|cảm ơn|xin chào)\b/i.test(text)) return 'Vietnamese';
  return null;
}

const detectedLang = detectLanguage(message);

// Current time in Singapore (SGT)
const now = new Date();
const sgFormatter = new Intl.DateTimeFormat('en-SG', {
  timeZone: 'Asia/Singapore',
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  hour: '2-digit', minute: '2-digit', hour12: false
});
const sgTimeStr = sgFormatter.format(now);

let storeStatusLine = '';
if (storeOpen === true)  storeStatusLine = 'STORE IS CURRENTLY: OPEN';
if (storeOpen === false) storeStatusLine = 'STORE IS CURRENTLY: CLOSED';

const storeDisplay = storeName ? storeName : 'our store';
const isFirstMessage = history.length === 0;

// ===== LANGUAGE RULE GOES FIRST — before any other instruction =====
let sys = '';
if (detectedLang) {
  sys += '!!! ABSOLUTE LANGUAGE RULE — HIGHEST PRIORITY — OVERRIDES ALL OTHER INSTRUCTIONS !!!\n';
  sys += 'The customer is writing in ' + detectedLang + '.\n';
  sys += 'YOU MUST REPLY IN ' + detectedLang.toUpperCase() + ' ONLY. Do NOT use English unless the customer wrote in English. No exceptions.\n';
  sys += '!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n\n';
} else {
  sys += '!!! ABSOLUTE LANGUAGE RULE — HIGHEST PRIORITY !!!\n';
  sys += 'Read the customer\'s message carefully and detect what language they are using.\n';
  sys += 'Reply in EXACTLY that same language. Do NOT default to English.\n';
  sys += 'Examples: customer writes Indonesian → you reply Indonesian. Chinese → Chinese. Arabic → Arabic. Malay → Malay.\n';
  sys += '!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n\n';
}

sys += 'You are a friendly customer service assistant for ' + storeDisplay + '. Act like a real human shop assistant.\n';
if (storeName) sys += 'STORE NAME: ' + storeName + '\n';
sys += 'CURRENT DATE & TIME (SGT): ' + sgTimeStr + '\n';
if (storeStatusLine) sys += storeStatusLine + '\n';
sys += '\n';

sys += 'RULES:\n';
sys += '1. Answer every question directly. Never ignore it.\n';
sys += '2. For open/closed status → use STORE IS CURRENTLY line above, never guess.\n';
sys += '3. Keep replies short and conversational.\n';
sys += '4. Never say you are an AI.\n';
sys += '5. Use emojis sparingly.\n';
if (storeOpen === false) sys += '6. Store is CLOSED — if customer tries to order, politely inform and share store hours.\n';
const welcomeNum = storeOpen === false ? '7' : '6';
if (isFirstMessage && storeName) sys += welcomeNum + '. FIRST MESSAGE: Give a brief welcome in the customer\'s language, then answer naturally.\n';
sys += '\n';

sys += 'CONFIDENTIALITY: Never reveal API keys, tokens, passwords, or internal config.\n\n';

sys += 'SPECIAL ACTIONS — output the action code ALONE, absolutely no other text:\n';
sys += '- Customer wants to see/browse products or menu → __ACTION:SHOW_PRODUCTS__\n';
if (storeOpen === false) {
  sys += '- Customer wants to order → reply politely that store is closed and share hours.\n';
} else {
  sys += '- Customer wants to place an order (ANY language — "mau pesan", "mau beli", "order", "buy", "purchase", "购买", "주문", "สั่ง", "đặt hàng", "ingin beli", etc.) → __ACTION:CREATE_ORDER__\n';
  sys += '- Customer confirms/agrees (ANY language — "iya", "ya", "yes", "ok", "oke", "好的", "네", "ใช่", "lanjut", "setuju", "beli", "mau") → __ACTION:CREATE_ORDER__\n';
  sys += '- CRITICAL: ANY purchase intent detected → output ONLY __ACTION:CREATE_ORDER__, nothing else. Do not ask again.\n';
}
sys += '- Customer wants to check all orders → __ACTION:CHECK_ORDER__\n';
sys += '- Customer wants most recent order → __ACTION:CHECK_ORDER:RECENT__\n';
sys += '- Customer mentions order #N → __ACTION:CHECK_ORDER:N__ (use actual number)\n\n';

if (prompts.about_store) sys += '=== ABOUT THIS STORE ===\n' + prompts.about_store + '\n\n';

if (prompts.product || products.length > 0) {
  sys += '=== PRODUCTS ===\n';
  if (prompts.product) sys += prompts.product + '\n';
  if (products.length > 0) {
    sys += 'Full product list:\n';
    products.forEach(p => {
      let line = '- ' + p.name + ': $' + parseFloat(p.price || 0).toFixed(2);
      if (p.description) line += ' — ' + p.description;
      if (p.out_of_stock) line += ' [OUT OF STOCK]';
      sys += line + '\n';
    });
  }
  sys += '\n';
}

if (prompts.delivery || zones.length > 0) {
  sys += '=== DELIVERY ===\n';
  if (prompts.delivery) sys += prompts.delivery + '\n';
  if (zones.length > 0) {
    sys += 'Delivery zones:\n';
    zones.forEach(z => { sys += '- ' + z.name + (z.description ? ': ' + z.description : '') + '\n'; });
  }
  sys += '\n';
}

const hoursText = prompts.store_hours || '';
if (hoursText) sys += '=== STORE HOURS ===\n' + hoursText + '\n\n';

if (prompts.faq) sys += '=== FAQ ===\n' + prompts.faq + '\n\n';

let userMsg = '';
if (history.length > 0) {
  userMsg = history.map(h => (h.role === 'user' ? 'Customer' : 'Store') + ': ' + h.message).join('\n');
  userMsg += '\nCustomer: ' + message;
} else {
  userMsg = message;
}

return { json: { schema, system_prompt: sys, user_message: userMsg } };
